def transform(grid):
    """Translate the grid contents down by one row, clipping at the bottom."""
    h = len(grid)
    if h == 0:
        return []
    w = len(grid[0])
    out = [[0 for _ in range(w)] for _ in range(h)]
    for r in range(h - 1):
        out[r + 1] = list(grid[r])
    return out
